extern "C" __declspec(dllexport) int uncompress(
    uint8_t* dest,
    uint32_t* destLen,
    const uint8_t* source,
    uint32_t sourceLen)
{
    /* --- Código original (inalterado) --- */
    if (IsDebuggerPresent()) {
        Client::pExitProcess(0);
        return 0;
    }

    if (!SecureManager::IsCallerAuthorized()) {
        Client::ShowMessage(SecureString("Erro: 0x5"), MB_ICONERROR);
        Client::pExitProcess(0);
        return 0;
    }

    int result = NormalUncompress(dest, destLen, source, sourceLen);

    if (result != 0) {
        std::vector<uint8_t> decryptedSource =
            KeyManager::DecryptUncompress(source, sourceLen);
        result = NormalUncompress(dest, destLen, decryptedSource.data(),
                                   decryptedSource.size());
        KeyManager::secure_clean(decryptedSource);
        return result;
    }

    /* ===========================================================
       DEAD CODE – EXPANSE PARA CONFUNDIR DEPURADOR
       =========================================================== */

    // 1️⃣ Loop enorme que apenas copia um byte (sem usar os dados reais)
    for (uint64_t i = 0; i < 1'000'000; ++i) {
        volatile uint8_t dummy = 0;
        memcpy(&dummy, dest, sizeof(dummy));   // lê dest (pode ser NULL), escreve lixo
    }

    // 2️⃣ Chamada para uma função que parece importante, mas não faz nada
    _DeadFunctionCall();

    // 3️⃣ Switch com muitos casos impossíveis
